/* Shared Festival rules and bundled illustration. Server actions authorize all payments. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.MiniopolyFestival=api;})(typeof window==='undefined'?globalThis:window,function(){
 'use strict';
 const fund=value=>Number.isSafeInteger(value)&&value>=0?value:0;
 function shares(total,players,visitor){
  if(!Number.isSafeInteger(total)||total<0||!Number.isInteger(visitor)||!players[visitor]||players[visitor].out)throw Error('Invalid festival distribution.');
  const others=Array.from({length:players.length-1},(_,i)=>(visitor+i+1)%players.length).filter(seat=>!players[seat].out);
  // Integer arithmetic avoids fractional dollars, including near the safe-integer bound.
  const visitorShare=others.length?Math.floor(total/5)*3+Math.floor((total%5)*3/5):total;
  const remainder=total-visitorShare,each=others.length?Math.floor(remainder/others.length):0,extra=others.length?remainder%others.length:0;
  return [visitor,...others].map((seat,index)=>({playerId:players[seat].id||'seat-'+seat,seat,name:players[seat].name,visitor:index===0,amount:index===0?visitorShare:each+(index<=extra?1:0)}));
 }
 function distribute(room,visitor){
  const total=fund(room.festivalFund),payouts=shares(total,room.players,visitor);
  if(payouts.some(p=>!Number.isSafeInteger(room.players[p.seat].cash+p.amount)))throw Error('The festival payment exceeds the supported cash balance.');
  for(const p of payouts)room.players[p.seat].cash+=p.amount;
  room.festivalFund=0;return {total,shares:payouts};
 }
 function taxName(obligation){
  if(!obligation||obligation.creditor!==null)return null;
  const match=/^(Town Tax|Storm Fund) · \$(100|125)$/.exec(obligation.description||'');
  return match&&obligation.amount===(match[1]==='Town Tax'?100:125)?match[1]:null;
 }
 const art='data:image/webp;base64,';
 const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 768 768"><image width="768" height="768" href="'+art+'"/></svg>';
 return Object.freeze({fund,shares,distribute,taxName,art,svg});
});
